    {
      "id": "computeDiscrepancy",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Compute Discrepancy"
      },
      "inputs": {
        "script": "var erpResult = $vars.queryErpRecords1.output;\nvar crmResult = $vars.queryCrmRecords1.output;\n\nvar erpRecords = (erpResult && erpResult.value) ? erpResult.value : (Array.isArray(erpResult) ? erpResult : []);\nvar crmRecords = (crmResult && crmResult.value) ? crmResult.value : (Array.isArray(crmResult) ? crmResult : []);\n\nvar lineNumber = Number($vars.disputedLineNumber);\nvar matchedLine = null;\nfor (var i = 0; i < erpRecords.length; i++) {\n  if (Number(erpRecords[i].lineNumber) === lineNumber) {\n    matchedLine = erpRecords[i];\n    break;\n  }\n}\n\nvar contractedAmount = matchedLine ? Number(matchedLine.amount) : 0;\n\nvar firstErp = erpRecords.length > 0 ? erpRecords[0] : null;\nvar matchedInvoiceNumber = firstErp ? String(firstErp.invoiceNumber) : String($vars.invoiceNumber);\n\nvar firstCrm = crmRecords.length > 0 ? crmRecords[0] : null;\nvar accountTier = firstCrm ? String(firstCrm.accountTier) : \"\";\n\nvar invoicedAmount = Number($vars.disputedUnitPrice) * Number($vars.disputedQuantity);\nvar rawOvercharge = invoicedAmount - contractedAmount;\nvar totalOvercharge = rawOvercharge > 0 ? rawOvercharge : 0;\nvar discrepancyCount = totalOvercharge > 0 ? 1 : 0;\n\nreturn { totalOvercharge: totalOvercharge, discrepancyCount: discrepancyCount, matchedInvoiceNumber: matchedInvoiceNumber, accountTier: accountTier };"
