      "typeVersion": "1.0",
      "display": {
        "label": "Done"
      },
      "inputs": {},
      "outputs": {
        "totalOvercharge": {
          "source": "=js:$vars.computeDiscrepancy.output.totalOvercharge"
        },
        "discrepancyCount": {
          "source": "=js:$vars.computeDiscrepancy.output.discrepancyCount"
        },
        "matchedInvoiceNumber": {
          "source": "=js:$vars.computeDiscrepancy.output.matchedInvoiceNumber"
